import os
import torch


class Config:
    # ==== General Settings ====
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset for debugging
    DEBUG_SAMPLE_SIZE = 200
    NUM_WORKERS = 4

    # ==== Paths ====
    # Input Metadata (Generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output Directory
    WORKING_DIR = "./working/idea_11"
    OUTPUT_DIR = os.path.join(WORKING_DIR, "output")
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create directories
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==== Model Architecture ====
    MODEL_NAME = "microsoft/deberta-v3-large"
    MAX_LENGTH = 512  # Max length per branch (Prompt + Response)
    DROPOUT = 0.0  # Dropout probability for the classifier head

    # Decoupled Pooling Settings
    NUM_POOLING_LAYERS = 4  # Number of last layers to pool from
    HIDDEN_SIZE = 1024  # Hidden size of DeBERTa-v3-Large

    # ==== Feature Engineering ====
    USE_SCALARS = True  # Whether to use scalar features (lengths)
    NUM_SCALARS = 3  # log(len_prompt), log(len_resp_a), log(len_resp_b)

    # ==== Training Dynamics ====
    # Effective Batch Size = TRAIN_BATCH_SIZE * GRAD_ACCUM_STEPS
    # Target: 64. A100 40GB can handle BS=4 with DeBERTa-Large + Grad Checkpointing
    TRAIN_BATCH_SIZE = 4
    VALID_BATCH_SIZE = 8
    GRAD_ACCUM_STEPS = 16

    EPOCHS = 3
    LEARNING_RATE = 5e-6
    WEIGHT_DECAY = 0.01
    WARMUP_RATIO = 0.1
    MAX_GRAD_NORM = 1.0

    # Optimization
    FP16 = True
    GRAD_CHECKPOINTING = True

    # Early Stopping
    PATIENCE = 3  # Stop if validation loss doesn't improve for 3 evaluations
    EVAL_STEPS = 0.5  # Evaluate every 0.5 epochs (0.5 means twice per epoch)

    # ==== Target Definition ====
    TARGET_COLS = ["winner_model_a", "winner_model_b", "winner_tie"]
    NUM_LABELS = 3

    # ==== Hardware ====
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def print_config(cls):
        print("=" * 30)
        print(f"Configuration: {cls.__name__}")
        print("=" * 30)
        for key, value in cls.__dict__.items():
            if not key.startswith("__") and not callable(value):
                print(f"{key}: {value}")
        print("=" * 30)
